arguments.argument:
// 数値をキーボードから入力指定

switch show_menu("
Set Flag - Change Fart Sound Pitch Randomly ("+bool2string(global.fart_sound_pitch)+")"
  ,-1) {
  case 0: // interval max
    global.fart_sound_pitch = !global.fart_sound_pitch;
    if( global.fart_sound_pitch )
        draw_text_on_board("Fart Sound Pitch changes randomly", true);
    else
        draw_text_on_board("Fart Sound Pitch doesnt change", true);
  break;
 
  default:
  break;
  
}
